import React from 'react';
import {cva} from 'class-variance-authority';
const classes = ({tone="primary",size="sm",className}) => ["inline-flex items-center justify-center rounded font-medium disabled:opacity-50",(tone === "primary" ? "bg-action text-on-action" : "bg-slate-100 text-slate-900"),(size === "sm" ? "px-3 py-1 text-sm" : "px-4 py-2 text-base"),className].filter(Boolean).join(" ");
export default function ActionButton({tone,size,className,...props}) {
