const styles = {root:"tabular-nums font-medium"};
import React from 'react';
import {formatAmount} from '../shared/format.mjs';
export default function Amount({value}) {
  return <output className={styles.root} aria-label="금액">{formatAmount(value)}</output>;
}

import ActionButton from './ActionButton.jsx';
import React from 'react';
import {useAction} from './useAction.mjs';
export default function CheckoutForm({checkout, input}) {
  const action = useAction(() => checkout.submit(input));
  return <section><ActionButton disabled={action.pending} onClick={action.run}>결제</ActionButton>
    {action.result && <output>{action.result.order.id}</output>}
    {action.error && <p role="alert">결제에 실패했습니다.</p>}</section>;
}

import PanelCard from './PanelCard.jsx';
import ActionButton from './ActionButton.jsx';
import React from 'react';
import {useAction} from './useAction.mjs';
import Status from './Status.jsx';
export default function InventoryPanel({inventory}) {
  const action = useAction(async () => { await inventory.load(); return inventory.getState(); });
  const state = action.result ?? inventory.getState();
  return <PanelCard aria-label="재고"><ActionButton disabled={action.pending} onClick={action.run}>재고 조회</ActionButton>
    <Status state={state}/><ul>{state.items.map(item => <li key={item.id}>{item.sku}: {item.available}</li>)}</ul></PanelCard>;
}

